public sealed record CreateProductRequest(string? Name, string? Sku, decimal Price, string[]? Tags);
public sealed record ProductDto(string Id, string Sku, string Name, decimal Price, IReadOnlyList<string> Tags);

// Mapping is plain code: explicit, easy to step through, and checked by the compiler.
public static class ProductMapping
{
    public static ProductDto ToDto(this Product entity) =>
        new(entity.Id, entity.Sku, entity.Name, entity.Price, entity.Tags.Select(t => t.Name).ToList());
}

app.MapPost("/products", async (CreateProductRequest request, AppDbContext db, CancellationToken ct) =>
{
    var errors = CreateProductValidator.Validate(request);           // Dictionary<string, string[]>
    if (errors.Count > 0) return Results.ValidationProblem(errors);  // 400

    var sku = request.Sku!.Trim().ToUpperInvariant();
    if (await db.Products.AnyAsync(p => p.Sku == sku, ct))
        return Results.Conflict();                                   // 409

    var product = Product.Create(sku, request.Name!.Trim(), request.Price, request.Tags);
    db.Products.Add(product);
    await db.SaveChangesAsync(ct);                                   // a unique index still guards races

    return Results.Created($"/products/{product.Id}", product.ToDto()); // 201
});
